import numpy as np
from analyse import BASE,sha
def read(p):return list(csv.DictReader(p.open()))
def main():
 p=argparse.ArgumentParser();p.add_argument('--tag',required=True);p.add_argument('--case',required=True);a=p.parse_args();out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);src=BASE/'results'/a.case;run=json.loads((src/'summary.json').read_text());protocol=json.loads((src/'holding_protocol.json').read_text());rows=read(src/'object.csv');assert len(rows)==800 and run['duration_s']==2.;tree=ET.parse(src/'scene.scn');root=tree.getroot();dt=float(root.get('dt'));t=np.array([float(r['time_s']) for r in rows]);q=np.array([np.fromstring(r['rigid_q'],sep=' ') for r in rows]);v=np.array([np.fromstring(r['rigid_v'],sep=' ') for r in rows]);total=np.array([np.fromstring(r['object_impulse_Ns_Nms'],sep=' ') for r in rows]);index={x:i for i,x in enumerate(t)};parts={n:np.zeros_like(total) for n in ('skin','rail','guide','support','other')};pairs={};seen=set()
 for r in read(src/'response_rows.csv'):
  paths=(r['model0'],r['model1'])
  if not any('/object/'in x for x in paths):continue
  key=(float(r['time_s']),int(r['row_id']));assert key not in seen;seen.add(key);other=paths[1] if '/object/'in paths[0] else paths[0];name='skin' if '/skinCollision/'in other else 'rail' if '/railCollision/'in other else 'guide' if '/guides'in other else 'support' if '/floor/'in other else 'other';parts[name][index[key[0]]]+=np.fromstring(r['object_impulse_Ns_Nms'],sep=' ');pairs[other]=pairs.get(other,0)+1
 window=(t>=protocol['window_s'][0]-1e-12)&(t<=protocol['window_s'][1]+1e-12);ref=int(np.argmin(abs(t-protocol['reference_s'])));support=read(src/'support.csv');assert np.array_equal(np.array([float(r['time_s']) for r in support]),t);sq=np.array([np.fromstring(r['q'],sep=' ') for r in support]);R=float(root.find("Node[@name='object']/Node/SphereCollisionModel").get('radius'));supportR=float(root.find("Node[@name='floor']/SphereCollisionModel").get('radius'));gap=np.linalg.norm(q[:,:3]-sq,axis=1)-R-supportR;slip=float((q[ref,2]-q[window,2]).max()*1000);speed=float(np.linalg.norm(v[window,:3],axis=1).max()*1000);partition=float(abs(total-sum(parts.values())).max());mass=float(root.find("Node[@name='object']/UniformMass").get('vertexMass').split()[0]);gravity=np.fromstring(root.get('gravity'),sep=' ');assert mass==protocol['mass_kg'] and np.array_equal(gravity,protocol['gravity_m_s2'])
 momentum=mass*(v[:,:3]-np.vstack([np.zeros((1,3)),v[:-1,:3]]))-total[:,:3]-mass*gravity*dt;momentum_error=float(abs(momentum[window]).max());forces={n:dict(mean_force_N=(z[window,:3]/dt).mean(0).tolist(),maximum_resultant_N=float(np.linalg.norm(z[window,:3]/dt,axis=1).max())) for n,z in parts.items()};detector_skin=0
 with (src/'detector.csv').open() as f:
  for r in csv.DictReader(f):
   time=float(r['accepted_time_s']);names=(r['model0'],r['model1'])
   if protocol['window_s'][0]-1e-12<=time<=protocol['window_s'][1]+1e-12 and any('/object/'in x for x in names) and any('/skinCollision/'in x for x in names):detector_skin+=1
 tests=dict(actual_full_Native=run['status']=='VALID_BOUNDED_EXPLORATION_ONLY',slip=slip<=protocol['max_vertical_slip_mm'],speed=speed<=protocol['max_speed_mm_s'],support_gap=float(gap[window].min()*1000)>=protocol['minimum_support_surface_gap_mm'],support_force=forces['support']['maximum_resultant_N']<=protocol['maximum_support_resultant_N'],guide_force=forces['guide']['maximum_resultant_N']<=1e-5,rail_force=forces['rail']['maximum_resultant_N']<=1e-5,other_hidden_load=forces['other']['maximum_resultant_N']<=1e-5,source_partition=partition<=1e-12,momentum=momentum_error<=protocol['gravity_momentum_impulse_residual_limit_Ns'],direct_skin_detector_and_force=detector_skin>0 and forces['skin']['mean_force_N'][2]>0,positive_all_saved_elements=all(r['finite'] and r['minimum_saved_volume_ratio']>0 for r in run['qualities']));tests={k:bool(v) for k,v in tests.items()};iterations=max(int(r['solver_iterations']) for r,w in zip(rows,window) if w)
 finite=bool(np.isfinite(q).all() and np.isfinite(v).all());quaternion_error=float(np.max(abs(np.linalg.norm(q[:,3:],axis=1)-1))) if finite else None;object_node=root.find("Node[@name='object']");fixed=any('ProjectiveConstraint'in x.tag or 'RestShapeSprings'in x.tag for x in object_node.iter());command_error=0.;approach=[];skin_approach=[];local=np.array(json.loads((src/'mesh.json').read_text())['local_positions_mm']);tipmask=(local[:,0]==100)&(local[:,2]==.1);centre0=np.fromstring(object_node.find('MechanicalObject').get('position'),sep=' ')[:3];stations=[(local[:,0]==x)&(local[:,2]==.1) for x in np.unique(local[:,0]) if x>=70]
 assert not (src/'latch0.csv').exists(),'Length-mode goal needs explicit actual-input audit,not pre-override command fields'
 for i in range(3):
  film=read(src/f'finger{i}.csv');assert [float(r['time_s']) for r in film]==t.tolist();q0=np.fromstring(root.find(f"Node[@name='finger{i}']/MechanicalObject").get('position'),sep=' ').reshape(-1,3);actual=np.array([np.fromstring(r['q_m'],sep=' ').reshape(-1,3) for r in film]);initial_tip=q0[tipmask].mean(0);qtip=actual[:,tipmask].mean(1);approach.append(float(np.linalg.norm(initial_tip[:2])-np.linalg.norm(qtip[:,:2],axis=1).min()));r0=np.linalg.norm(np.array([q0[m].mean(0) for m in stations])-centre0,axis=1);radii=np.array([np.linalg.norm(actual[:,m].mean(1)-centre0,axis=1) for m in stations]).T;skin_approach.append(float((r0-radii[t<=.6+1e-12]).max()))
  for r in film:
   for j in range(2):command_error=max(command_error,abs(float(r[f'cable{j}_force_raw'])-float(r['command_Ns'])))
 tests.update(finite_object=finite,unit_quaternion=bool(finite and quaternion_error<=1e-12),object_not_projectively_fixed=not fixed,all_three_actual_skin_approach=all(x>0 for x in skin_approach),actual_cable_force_command_consistent=command_error<=1e-12)
 from scipy.spatial.transform import Rotation
