 d=dict(status='EXPLORATORY_FUNCTIONAL_GRASP_PASS' if all(tests.values()) else 'FAIL_EXPLORATORY_FUNCTIONAL_GRASP',tests=tests,case=a.case,protocol=protocol,slip_mm=slip,maximum_speed_mm_s=speed,minimum_support_gap_mm=float(gap[window].min()*1000),force_partition=forces,partition_error_Ns_Nms=partition,maximum_hold_momentum_residual_Ns=momentum_error,hold_detector_skin_outputs=detector_skin,hold_solver_max_iterations=iterations,solver_iteration_limit_reached=iterations>int(root.find('BlockGaussSeidelConstraintSolver').get('maxIterations')),gravity_load_N=float(-mass*gravity[2]),response_model_paths=pairs,maximum_object_quaternion_norm_error=quaternion_error,maximum_hold_rotation_from_1s_deg=rotation_degrees,maximum_hold_angular_speed_rad_s=float(np.linalg.norm(v[window,3:],axis=1).max()),actual_radial_tip_approach_m=approach,actual_widthmean_distal_skin_approach_m=skin_approach,approach_scope='Maximum inwardmotion ofwidthmeanSkin stations70–100 relativeFIXEDinitialobjectcentre before.6s;tip-onlymotion inventoryNOTa graspcriterion. No objectmotion used tofakeapproach.',maximum_cable_force_command_error_Ns=command_error,physical_validation='NOT QUALIFIED',time_mesh_convergence='Existing FAIL unchanged',pressure=None,source_commit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),source_sha256=sha(Path(__file__)),input_hashes={f:sha(src/f) for f in ('scene.scn','summary.json','preflight.json','holding_protocol.json','object.csv','support.csv','response_rows.csv','detector.csv')});(out/'summary.json').write_text(json.dumps(d,indent=2));(out/'producer.py').write_bytes(Path(__file__).read_bytes());print(json.dumps(d,indent=2))
